#!/usr/bin/env bash
# Breezelabs agents sync.
#
# Generates the agent configuration (instructions, skills, MCP servers) for
# the agents configured in rulesync.jsonc, using rulesync:
#   - global:   company .rulesync/ (this repo) + personal .rulesync/
#               -> user-level folders (~/.claude, ~/.copilot, ...)
#   - projects: <repo>/.rulesync/ -> project-level folders, for every repo
#               under repos_root
#
# Every source file carries the marker below, so generated files can be told
# apart from hand-written ones. Before writing, a dry run lists all changes;
# hand-written files are only overwritten or deleted after confirmation.
set -euo pipefail

RULESYNC_VERSION="24.0.0"
MARKER="generated by breezelabs-sync"
MARKER_LINE="<!-- $MARKER: edit the source in the company, personal or project .rulesync/ folder instead -->"
HOOK_MARKER="# breezelabs-sync hook"
HOOKS=(post-checkout post-merge post-commit)
# Defaults for project repos without their own rulesync.jsonc. (rulesync only
# reads config files inside the project, so these are passed as flags.)
# claudecode writes .mcp.json, copilot writes .vscode/mcp.json.
PROJECT_TARGETS="claudecode,copilot"
PROJECT_FEATURES="rules,skills,mcp"

AGENTS_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
CONFIG_FILE="$AGENTS_DIR/config.yaml"

usage() {
  cat <<EOF
Usage: sync.sh [command] [options]

Commands:
  all              Sync global and all projects (default)
  global           Sync company + personal sources into the user-level agent folders
  projects         Sync every repo under repos_root that has a .rulesync/ folder
                   (skips repos whose git hooks keep them in sync)
  project <path>   Sync a single repo
  install-hooks    Install git hooks (${HOOKS[*]}) in all project repos

Options:
  -n, --dry-run    Only show what would change
  -y, --yes        Overwrite/delete hand-written files without asking
  -h, --help       Show this help

Environment (mainly for testing):
  SYNC_HOME           Home folder to write the global configuration to (default: \$HOME)
  SYNC_WINDOWS_HOME   Overrides wsl_windows_home from config.yaml
EOF
}

warn() { echo "warning: $*" >&2; }
die() { echo "error: $*" >&2; exit 1; }

# Runs the pinned rulesync version. RS_HOME redirects the home folder used for
# global output (rulesync's HOME_DIR override).
rulesync() {
  if [ -n "${RS_HOME:-}" ]; then
    HOME_DIR="$RS_HOME" npx -y "rulesync@$RULESYNC_VERSION" "$@"
  else
    npx -y "rulesync@$RULESYNC_VERSION" "$@"
  fi
}

# Reads a top-level "key: value" entry from config.yaml.
config_value() {
  sed -n "s/^$1:[[:space:]]*\"\{0,1\}\([^\"]*\)\"\{0,1\}[[:space:]]*\$/\1/p" "$CONFIG_FILE" | head -n 1
}

detect_os() {
  case "$(uname -s)" in
    Darwin) echo macos ;;
    Linux)
      if grep -qi microsoft /proc/version 2>/dev/null; then echo wsl; else echo linux; fi ;;
    *) echo unsupported ;;
  esac
}

# Appends the marker to rules and skills installed from external sources
# (.curated/), which can't carry it upstream. rulesync install leaves the
# appended line alone, and a re-install that rewrites a file just gets it again.
mark_curated() {
  local tree="$1" file
  [ -d "$tree" ] || return 0
  while IFS= read -r -d '' file; do
    grep -qF "$MARKER" "$file" || printf '\n%s\n' "$MARKER_LINE" >>"$file"
  done < <(find "$tree" -path '*/.curated/*' -type f \( -path '*/rules/.curated/*.md' -o -name SKILL.md \) -print0)
}

# Fails if a rule or skill in a source tree lacks the generated-file marker.
check_markers() {
  local tree="$1" file missing=0
  [ -d "$tree" ] || return 0
  while IFS= read -r -d '' file; do
    if ! grep -qF "$MARKER" "$file"; then
      echo "  $file" >&2
      missing=1
    fi
  done < <(find "$tree" -type f \( -path '*/rules/*.md' -o -name SKILL.md \) -print0)
  if [ "$missing" = 1 ]; then
    die "the files above lack the marker; append this line to each:
  $MARKER_LINE"
  fi
}

# A path counts as generated if it carries the marker. A skill is judged by
# its SKILL.md, since only that file carries the marker. MCP configs are JSON,
# which rulesync merges into the agent's own config, so they can't be marked.
is_generated() {
  local path="$1"
  case "$path" in *.json | *.jsonc) return 0 ;; esac
  [ -d "$path" ] && path="$path/SKILL.md"
  grep -qF "$MARKER" "$path" 2>/dev/null
}

# Runs rulesync generate as a dry run and prints every change it would make,
# one line per skill rather than per skill file.
# Sets CHANGES (number of changes) and HANDWRITTEN (1 if hand-written files
# would be overwritten or deleted).
plan() {
  local dir="$1" out line path action
  local seen=$'\n'
  shift
  CHANGES=0
  HANDWRITTEN=0
  out="$(cd "$dir" && rulesync generate "$@" --delete --dry-run 2>&1)" || { echo "$out" >&2; die "rulesync failed in $dir"; }
  while IFS= read -r line; do
    case "$line" in
      *"Would write: "*) path="${line#*Would write: }"; action=write ;;
      *"Would delete directory: "*) path="${line#*Would delete directory: }"; path="${path//\"/}"; action=delete ;;
      *"Would delete: "*) path="${line#*Would delete: }"; action=delete ;;
      *) continue ;;
    esac
    # Files inside an agent's skill folder (e.g. ~/.claude/skills/uv/...) count as the skill.
    if [[ "$path" =~ ^(.*/\.[^/]+/skills/[^/]+)/ ]]; then path="${BASH_REMATCH[1]}"; fi
    [[ "$seen" == *$'\n'"$path"$'\n'* ]] && continue
    seen+="$path"$'\n'
    CHANGES=$((CHANGES + 1))
    if [ ! -e "$path" ]; then
      echo "  new        $path"
    elif is_generated "$path"; then
      if [ "$action" = write ]; then echo "  update     $path"; else echo "  remove     $path (stale)"; fi
    else
      HANDWRITTEN=1
      if [ "$action" = write ]; then echo "  OVERWRITE  $path (not generated)"; else echo "  DELETE     $path (not generated)"; fi
    fi
  done <<<"$out"
}

# Plans, confirms and runs one rulesync generate.
run_generate() {
  local label="$1" dir="$2" answer
  shift 2
  echo "== $label"
  plan "$dir" "$@"
  if [ "$CHANGES" = 0 ]; then echo "  up to date"; return 0; fi
  [ "$DRY_RUN" = 1 ] && return 0
  if [ "$HANDWRITTEN" = 1 ] && [ "$YES" != 1 ]; then
    if [ "$HOOK" = 1 ] || [ ! -t 0 ]; then
      warn "skipped $label: it would overwrite or delete files that are not generated (marked above)."
      warn "Move their content into a .rulesync/ source, or run sync.sh --yes."
      return 0
    fi
    read -r -p "Overwrite/delete the files marked as not generated? [y/N] " answer
    [[ "$answer" =~ ^[yY]$ ]] || { echo "  skipped"; return 0; }
  fi
  (cd "$dir" && rulesync generate "$@" --delete --silent)
  echo "  done"
}

# Prepares a repo's .rulesync/ source tree: installs external rules/skills
# declared in its rulesync.jsonc (at the versions pinned in rulesync.lock),
# marks them as generated, and checks that every source carries the marker.
prepare_sources() {
  local repo="$1"
  if [ -f "$repo/rulesync.lock" ] && [ "$DRY_RUN" != 1 ]; then
    (cd "$repo" && rulesync install --frozen --silent)
  fi
  mark_curated "$repo/.rulesync"
  check_markers "$repo/.rulesync"
}

sync_global() {
  local roots=("$AGENTS_DIR/.rulesync")
  prepare_sources "$AGENTS_DIR"
  if [ -d "$PERSONAL_DIR/.rulesync" ]; then
    prepare_sources "$PERSONAL_DIR"
    roots+=("$PERSONAL_DIR/.rulesync")
  else
    warn "no personal sources found at $PERSONAL_DIR/.rulesync"
  fi

  RS_HOME="${SYNC_HOME:-}" run_generate "global" "$AGENTS_DIR" \
    --global -c "$AGENTS_DIR/rulesync.jsonc" --input-roots "${roots[@]}"

  # Optional: VS Code windows opened on Windows folders read the Windows home.
  if [ "$OS" = wsl ] && [ -n "$WINDOWS_HOME" ]; then
    RS_HOME="$WINDOWS_HOME" run_generate "global, Windows side (VS Code)" "$AGENTS_DIR" \
      --global -c "$AGENTS_DIR/rulesync.wsl.jsonc" --input-roots "${roots[@]}"
  fi
}

sync_project() {
  local repo
  local args=()
  repo="$(cd "$1" && pwd)"
  [ -d "$repo/.rulesync" ] || { echo "== project $(basename "$repo"): no .rulesync/ folder, nothing to do"; return 0; }
  prepare_sources "$repo"
  if [ ! -f "$repo/rulesync.jsonc" ]; then
    # Without an mcp.jsonc source, rulesync reports MCP files as changed on every run.
    if [ -f "$repo/.rulesync/mcp.jsonc" ]; then
      args=(-t "$PROJECT_TARGETS" -f "$PROJECT_FEATURES")
    else
      args=(-t "$PROJECT_TARGETS" -f "${PROJECT_FEATURES/,mcp/}")
    fi
  fi
  run_generate "project $(basename "$repo")" "$repo" ${args[@]+"${args[@]}"}
}

# Lists repos under repos_root that have a .rulesync/ folder, excluding the
# company and personal repos (their sources are global).
project_repos() {
  local repo
  for repo in "$REPOS_ROOT"/*/; do
    repo="${repo%/}"
    [ -d "$repo/.rulesync" ] || continue
    { [ "$repo" -ef "$AGENTS_DIR" ] || [ "$repo" -ef "$PERSONAL_DIR" ]; } && continue
    echo "$repo"
  done
}

hooks_dir() {
  local dir
  dir="$(git -C "$1" rev-parse --git-path hooks 2>/dev/null)" || return 1
  [[ "$dir" = /* ]] || dir="$1/$dir"
  echo "$dir"
}

hooks_installed() {
  local dir
  dir="$(hooks_dir "$1")" || return 1
  grep -qF "$HOOK_MARKER" "$dir/${HOOKS[0]}" 2>/dev/null
}

sync_projects() {
  local repo
  while IFS= read -r repo; do
    if hooks_installed "$repo"; then
      echo "== project $(basename "$repo"): skipped, kept in sync by git hooks"
      continue
    fi
    sync_project "$repo"
  done < <(project_repos)
}

install_hooks() {
  local repo dir name file
  while IFS= read -r repo; do
    dir="$(hooks_dir "$repo")" || { warn "$repo is not a git repo, skipping"; continue; }
    mkdir -p "$dir"
    for name in "${HOOKS[@]}"; do
      file="$dir/$name"
      if [ -e "$file" ] && ! grep -qF "$HOOK_MARKER" "$file"; then
        warn "$file already exists and was not installed by sync.sh, skipping"
        continue
      fi
      [ "$DRY_RUN" = 1 ] && { echo "  would install $file"; continue; }
      cat >"$file" <<EOF
#!/usr/bin/env bash
$HOOK_MARKER
# Keeps the agent configuration generated from .rulesync/ up to date.
# Installed by $AGENTS_DIR/sync.sh install-hooks
"$AGENTS_DIR/sync.sh" project "\$(git rev-parse --show-toplevel)" --hook || true
EOF
      chmod +x "$file"
      echo "  installed $file"
    done
  done < <(project_repos)
}

COMMAND=all
PROJECT=""
DRY_RUN=0
YES=0
HOOK=0
while [ $# -gt 0 ]; do
  case "$1" in
    all | global | projects | install-hooks) COMMAND="$1" ;;
    project) COMMAND=project; PROJECT="${2:?project needs a path}"; shift ;;
    -n | --dry-run) DRY_RUN=1 ;;
    -y | --yes) YES=1 ;;
    --hook) HOOK=1 ;;
    -h | --help) usage; exit 0 ;;
    *) usage >&2; exit 1 ;;
  esac
  shift
done

[ -f "$CONFIG_FILE" ] || die "missing $CONFIG_FILE"
PERSONAL_DIR="$(config_value agents_personal)"
REPOS_ROOT="$(config_value repos_root)"
WINDOWS_HOME="${SYNC_WINDOWS_HOME:-$(config_value wsl_windows_home)}"
PERSONAL_DIR="${PERSONAL_DIR/#\~/$HOME}"
REPOS_ROOT="${REPOS_ROOT/#\~/$HOME}"
OS="$(detect_os)"
[ "$OS" = unsupported ] && die "unsupported OS: $(uname -s)"
command -v npx >/dev/null || die "npx not found (install Node.js)"

case "$COMMAND" in
  all) sync_global; sync_projects ;;
  global) sync_global ;;
  projects) sync_projects ;;
  project) sync_project "$PROJECT" ;;
  install-hooks) install_hooks ;;
esac
